#!/usr/bin/env bash
# WAKHAN chat extras 1 (reactions, pinned message, typing). Adds native_chat_plus.py and one hook line
# in native_runtime.py. Backs up first and rolls back by itself when anything fails.
set -uo pipefail
WD=/opt/wakhan-app-0.2.11-li9z037x; SVC=wakhan-app; TS=$(date +%Y%m%d-%H%M%S); BK=$WD/backups/chatx1-$TS
RUNTIME_SHA=e8685e94446a1c59
say(){ printf '%s\n' "$*"; }
[ "$(id -u)" = 0 ] || { say "❌ با root اجرا کن"; exit 1; }
cd "$WD" || { say "❌ پوشهٔ برنامه پیدا نشد"; exit 1; }
if grep -q "native_chat_plus" native_runtime.py; then say "ℹ️ این بسته قبلاً نصب شده است. کاری انجام نشد."; exit 0; fi
CUR=$(sha256sum native_runtime.py | cut -c1-16)
[ "$CUR" = "$RUNTIME_SHA" ] || { say "❌ native_runtime.py تغییر کرده ($CUR). برای امنیت نصب انجام نشد. این خط را برای Claude بفرست."; exit 1; }
mkdir -p "$BK" && cp -p native_runtime.py "$BK/" || { say "❌ پشتیبان‌گیری ناکام شد"; exit 1; }
python3 - "$WD/data/music.db" "$BK/music.db" <<'PY' || { say "❌ پشتیبان پایگاه داده ناکام شد"; exit 1; }
import sqlite3,sys
src=sqlite3.connect(f'file:{sys.argv[1]}?mode=ro',uri=True);dst=sqlite3.connect(sys.argv[2]);src.backup(dst);dst.close();src.close()
PY
say "✅ پشتیبان: $BK"
rollback(){
  say "↩️ برگشت به حالت قبل…"
  cp -p "$BK/native_runtime.py" "$WD/native_runtime.py"; rm -f "$WD/native_chat_plus.py"
  systemctl restart $SVC; sleep 4; systemctl is-active --quiet $SVC && say "✅ سرویس به حالت قبل برگشت و روشن است." || say "⚠️ سرویس روشن نشد؛ خروجی را برای Claude بفرست."
  exit 1
}
echo "" | base64 -d > native_chat_plus.py || rollback
[ "$(sha256sum native_chat_plus.py | cut -c1-64)" = "a7c1084dd197a608a083dc4184a6141bc3004e3469a959876eb4e1b4d383a3fe" ] || { say "❌ فایل خراب است"; rollback; }
chown --reference=native_chat.py native_chat_plus.py; chmod --reference=native_chat.py native_chat_plus.py
python3 - <<'PY' || rollback
p='native_runtime.py';s=open(p,encoding='utf-8').read()
old='    install_chat(app,ns)\n'
assert s.count(old)==1,'hook point not found'
s=s.replace(old,old+'    from native_chat_plus import install as install_chat_plus\n    install_chat_plus(app,ns)\n')
open(p,'w',encoding='utf-8').write(s)
PY
sudo -u "$(stat -c %U native_chat.py)" python3 -m py_compile native_chat_plus.py native_runtime.py 2>&1 || rollback
systemctl restart $SVC; sleep 6
systemctl is-active --quiet $SVC || { journalctl -u $SVC -n 15 --no-pager | grep -iv "token\|secret\|key=" ; rollback; }
A=$(curl -s -o /dev/null -w '%{http_code}' -X POST http://127.0.0.1:10010/api/app/chatx/version)
B=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:10010/api/app/chat/inbox)
say "chatx=$A chat=$B"
{ [ "$A" != 404 ] && [ "$A" != 000 ] && [ "$B" != 000 ] && [ "$B" != 404 ]; } || rollback
python3 - "$WD/data/music.db" <<'PY'
import sqlite3,sys
c=sqlite3.connect(f'file:{sys.argv[1]}?mode=ro',uri=True)
print('tables:',[r[0] for r in c.execute("select name from sqlite_master where name like 'wkchatx_%' and type='table'")])
PY
say "✅ نصب شد: ریکشن، سنجاق پیام، در حال نوشتن"
say "برگشت دستی (اگر لازم شد): cp -p $BK/native_runtime.py $WD/ && rm -f $WD/native_chat_plus.py && systemctl restart $SVC"
